import { View, Text, SectionList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { name: "Чихэвч", cat: "Электроник" },
  { name: "Гар цаг", cat: "Электроник" },
  { name: "Гутал", cat: "Хувцас" },
  { name: "Цүнх", cat: "Хувцас" },
  { name: "Нарны шил", cat: "Гоёл" },
];

function App() {
  const cats = [...new Set(PRODUCTS.map((p) => p.cat))];
  const sections = cats.map((cat) => ({
    title: cat,
    data: PRODUCTS.filter((p) => p.cat === cat),
  }));
  return (
    <SectionList
      style={styles.screen}
      sections={sections}
      keyExtractor={(item, i) => item.name + i}
      renderSectionHeader={({ section }) => (
        <View testID="section-header" style={styles.header}>
          <Text style={styles.headerText}>{section.title}</Text>
        </View>
      )}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text>{item.name}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f8fafc" },
  header: { padding: 12, backgroundColor: "#e0e7ff" },
  headerText: { fontSize: 16, fontWeight: "bold", color: "#3730a3" },
  row: { padding: 16, backgroundColor: "#fff" },
});

registerRootComponent(App);
